<?php
require __DIR__.'/config.php';$me=require_staff();$pdo=db();$customerId=filter_input(INPUT_GET,'customer_id',FILTER_VALIDATE_INT);if(!$customerId||$customerId<1){http_response_code(404);exit('Customer not found.');}
$customerSql='SELECT c.customer_id,c.cif_number,c.full_name,c.full_name_bn,c.father_name,c.mother_name,c.spouse_name,c.date_of_birth,c.gender,c.nationality,c.profession,c.monthly_income,c.source_of_fund,c.tin_number,c.phone,c.email,c.id_type,c.id_number,c.status,c.kyc_status,c.registration_date,c.branch_id,b.branch_name,u.status AS login_status,u.last_login_at,u.failed_login_attempts FROM customers c JOIN branches b ON b.branch_id=c.branch_id LEFT JOIN users u ON u.linked_customer_id=c.customer_id WHERE c.customer_id=?';
$s=$pdo->prepare($customerSql);$s->execute([(int)$customerId]);$customer=$s->fetch();if(!$customer){http_response_code(404);exit('Customer not found.');}
if($me['role']!=='Administrator'){$access=$pdo->prepare('SELECT 1 FROM account_holders h JOIN accounts a ON a.account_id=h.account_id WHERE h.customer_id=? AND a.branch_id=? LIMIT 1');$access->execute([(int)$customerId,(int)$me['branch_id']]);if(!$access->fetchColumn()){http_response_code(404);exit('Customer not found.');}}
$accountSql="SELECT a.account_id,a.account_number,a.account_title,a.balance,a.currency,a.status,a.opening_date,a.closing_date,at.type_name,at.minimum_balance,b.branch_name,h.holder_role,h.operating_mode FROM account_holders h JOIN accounts a ON a.account_id=h.account_id JOIN account_types at ON at.account_type_id=a.account_type_id JOIN branches b ON b.branch_id=a.branch_id WHERE h.customer_id=?";$accountParams=[(int)$customerId];if($me['role']!=='Administrator'){$accountSql.=' AND a.branch_id=?';$accountParams[]=(int)$me['branch_id'];}$accountSql.=' ORDER BY h.holder_role DESC,a.account_id DESC';$s=$pdo->prepare($accountSql);$s->execute($accountParams);$accounts=$s->fetchAll();$accountIds=array_map('intval',array_column($accounts,'account_id'));$sum=array_sum(array_map(fn($a)=>(float)$a['balance'],$accounts));
$addresses=$pdo->prepare('SELECT address_type,address_line,post_office,thana,district,postal_code,country FROM addresses WHERE customer_id=? ORDER BY address_type,address_id');$addresses->execute([(int)$customerId]);$addresses=$addresses->fetchAll();foreach($addresses as &$address){$parts=[$address['address_line'],$address['post_office'],$address['thana'],$address['district'],$address['postal_code'],$address['country']];$address['formatted_address']=implode(', ',array_values(array_filter($parts,fn($part)=>$part!==null&&$part!=='')));}unset($address);$contacts=$pdo->prepare('SELECT contact_type,contact_value FROM customer_contacts WHERE customer_id=? ORDER BY contact_type,contact_id');$contacts->execute([(int)$customerId]);$contacts=$contacts->fetchAll();
$loans=$pdo->prepare('SELECT l.loan_id,l.loan_type,l.principal_amount,l.interest_rate,l.duration_months,l.application_date,l.monthly_installment,l.outstanding_balance,l.status,p.party_role FROM loan_parties p JOIN loans l ON l.loan_id=p.loan_id WHERE p.customer_id=? ORDER BY l.application_date DESC,l.loan_id DESC');$loans->execute([(int)$customerId]);$loans=$loans->fetchAll();
$cards=[];$nominees=[];$transactions=[];$transactionTotal=0;$page=max(1,(int)($_GET['page']??1));$perPage=50;$pages=1;
if($accountIds){$marks=implode(',',array_fill(0,count($accountIds),'?'));$cardsStmt=$pdo->prepare("SELECT c.card_id,c.account_id,c.card_type,c.masked_number,c.credit_limit,c.issue_date,c.expiry_date,c.status,a.account_number FROM cards c JOIN accounts a ON a.account_id=c.account_id WHERE c.customer_id=? AND c.account_id IN ($marks) ORDER BY c.card_id DESC");$cardsStmt->execute(array_merge([(int)$customerId],$accountIds));$cards=$cardsStmt->fetchAll();$nomineeStmt=$pdo->prepare("SELECT n.nominee_id,n.account_id,n.full_name,n.relationship,n.date_of_birth,n.share_percentage,a.account_number FROM nominees n JOIN accounts a ON a.account_id=n.account_id WHERE n.account_id IN ($marks) ORDER BY n.account_id,n.nominee_id");$nomineeStmt->execute($accountIds);$nominees=$nomineeStmt->fetchAll();$countStmt=$pdo->prepare("SELECT COUNT(*) FROM transactions WHERE account_id IN ($marks)");$countStmt->execute($accountIds);$transactionTotal=(int)$countStmt->fetchColumn();$pages=max(1,(int)ceil($transactionTotal/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$txStmt=$pdo->prepare("SELECT t.transaction_id,t.reference_number,t.account_id,t.transaction_type,t.amount,t.balance_before,t.balance_after,t.description,t.status,t.created_at,a.account_number FROM transactions t JOIN accounts a ON a.account_id=t.account_id WHERE t.account_id IN ($marks) ORDER BY t.created_at DESC,t.transaction_id DESC LIMIT $perPage OFFSET $offset");$txStmt->execute($accountIds);$transactions=$txStmt->fetchAll();}
$unread=db()->prepare('SELECT COUNT(*) FROM notifications n JOIN users u ON u.user_id=n.user_id WHERE u.linked_customer_id=? AND n.is_read=0');$unread->execute([(int)$customerId]);$unreadCount=(int)$unread->fetchColumn();$notificationStmt=$pdo->prepare('SELECT n.type,n.message,n.is_read,n.created_at FROM notifications n JOIN users u ON u.user_id=n.user_id WHERE u.linked_customer_id=? ORDER BY n.created_at DESC,n.notification_id DESC LIMIT 10');$notificationStmt->execute([(int)$customerId]);$notifications=$notificationStmt->fetchAll();page_start('Customer profile');?>
<div class="pagehead"><div><div class="eyebrow">Customer record</div><h1><?=e($customer['full_name'])?></h1><div class="muted">CIF <?=e($customer['cif_number'])?> · <?=e($customer['branch_name'])?></div></div><a class="button blue" href="<?=e(url('module.php?view=accounts'))?>">Back to account list</a></div>
<section class="profile-stats"><article><span>Linked accounts</span><strong><?=count($accounts)?></strong></article><article><span>Total balance</span><strong>BDT <?=e(number_format($sum,2))?></strong></article><article><span>Transactions</span><strong><?=number_format($transactionTotal)?></strong></article><article><span>Unread notifications</span><strong><?=$unreadCount?></strong></article></section>
<div class="profile-grid"><section class="panel"><h2>Customer details</h2><dl class="profile-dl"><dt>Customer status</dt><dd><?=e(ucfirst($customer['status']))?></dd><dt>KYC status</dt><dd><span class="pill"><?=e(ucfirst($customer['kyc_status']))?></span></dd><dt>Email</dt><dd><?=e($customer['email']??'—')?></dd><dt>Phone</dt><dd><?=e($customer['phone'])?></dd><dt>Date of birth</dt><dd><?=e($customer['date_of_birth'])?></dd><dt>Gender</dt><dd><?=e(ucfirst($customer['gender']))?></dd><dt>Nationality</dt><dd><?=e($customer['nationality'])?></dd><dt>Profession</dt><dd><?=e($customer['profession'])?></dd><dt>Identity</dt><dd><?=e(ucwords(str_replace('_',' ',$customer['id_type'])))?> · <?=e($customer['id_number'])?></dd><dt>Source of funds</dt><dd><?=e($customer['source_of_fund'])?></dd><dt>Registered</dt><dd><?=e($customer['registration_date'])?></dd><dt>Customer login</dt><dd><?=e(ucfirst($customer['login_status']??'Not set'))?><?=!empty($customer['last_login_at'])?' · Last login '.e($customer['last_login_at']):''?></dd></dl></section>
<section class="panel"><h2>Addresses &amp; contacts</h2><?php if($addresses):foreach($addresses as $address):?><div class="profile-address"><strong><?=e(ucfirst($address['address_type']))?> address</strong><p><?=e($address['formatted_address'])?></p></div><?php endforeach;else:?><p class="muted">No addresses recorded.</p><?php endif;?><?php if($contacts):?><h3>Additional contacts</h3><ul><?php foreach($contacts as $contact):?><li><?=e(ucwords(str_replace('_',' ',$contact['contact_type'])))?>: <?=e($contact['contact_value'])?></li><?php endforeach;?></ul><?php endif;?></section></div>
<div class="section-title"><h2>Accounts</h2><span class="muted"><?=count($accounts)?> linked</span></div><?php if($accounts):?><div class="panel table-scroll"><table><thead><tr><th>Account</th><th>Type</th><th>Branch</th><th>Holder</th><th>Balance</th><th>Status</th><th>Opened</th></tr></thead><tbody><?php foreach($accounts as $account):?><tr><td><?=e($account['account_number'])?><br><span class="muted"><?=e($account['account_title'])?></span></td><td><?=e($account['type_name'])?></td><td><?=e($account['branch_name'])?></td><td><?=e(ucfirst($account['holder_role']))?><br><span class="muted"><?=e(ucwords(str_replace('_',' ',$account['operating_mode'])))?></span></td><td>BDT <?=e(number_format((float)$account['balance'],2))?></td><td><span class="pill"><?=e(ucfirst($account['status']))?></span></td><td><?=e($account['opening_date'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="panel muted">No accounts are linked to this customer in your branch scope.</div><?php endif;?>
<div class="section-title"><h2>Transactions</h2><span class="muted">Latest <?=$transactionTotal?min($perPage,$transactionTotal):0?> of <?=number_format($transactionTotal)?></span></div><?php if($transactions):?><div class="panel table-scroll"><table><thead><tr><th>Date</th><th>Reference</th><th>Account</th><th>Type</th><th>Amount</th><th>Balance after</th><th>Status</th><th>Slip</th></tr></thead><tbody><?php foreach($transactions as $tx):?><tr><td><?=e($tx['created_at'])?></td><td><?=e($tx['reference_number'])?></td><td><?=e($tx['account_number'])?></td><td><?=e(ucwords(str_replace('_',' ',$tx['transaction_type'])))?></td><td>BDT <?=e(number_format((float)$tx['amount'],2))?></td><td>BDT <?=e(number_format((float)$tx['balance_after'],2))?></td><td><?=e(ucfirst($tx['status']))?></td><td><a class="button small blue" target="_blank" href="<?=e(url('slip.php?transaction_id='.(int)$tx['transaction_id']))?>">Print</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="panel muted">No transactions recorded for these accounts.</div><?php endif;?>
<?php if($pages>1):?><nav class="profile-pagination" aria-label="Transaction pages"><?php for($p=1;$p<=$pages;$p++):?><a class="<?=($p===$page?'current':'')?>" href="<?=e(url('customer_profile.php?customer_id='.(int)$customerId.'&page='.$p))?>"><?=$p?></a><?php endfor;?></nav><?php endif;?>
<div class="profile-grid"><section class="panel"><h2>Loans</h2><?php if($loans):?><div class="table-scroll"><table><thead><tr><th>Loan</th><th>Role</th><th>Principal</th><th>Outstanding</th><th>Status</th></tr></thead><tbody><?php foreach($loans as $loan):?><tr><td><?=e($loan['loan_type'])?><br><span class="muted"><?=e($loan['duration_months'])?> months · <?=e(number_format((float)$loan['interest_rate'],2))?>%</span></td><td><?=e(ucfirst($loan['party_role']))?></td><td>BDT <?=e(number_format((float)$loan['principal_amount'],2))?></td><td>BDT <?=e(number_format((float)$loan['outstanding_balance'],2))?></td><td><?=e(ucfirst($loan['status']))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No loans recorded.</p><?php endif;?></section><section class="panel"><h2>Cards</h2><?php if($cards):?><div class="table-scroll"><table><thead><tr><th>Masked card</th><th>Account</th><th>Type</th><th>Limit</th><th>Expiry</th><th>Status</th></tr></thead><tbody><?php foreach($cards as $card):?><tr><td><?=e($card['masked_number'])?></td><td><?=e($card['account_number'])?></td><td><?=e(ucfirst($card['card_type']))?></td><td><?=$card['credit_limit']===null?'—':'BDT '.e(number_format((float)$card['credit_limit'],2))?></td><td><?=e($card['expiry_date'])?></td><td><?=e(ucfirst($card['status']))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No cards issued to this customer in the accounts shown.</p><?php endif;?></section></div>
<section class="panel"><h2>Recent notifications</h2><?php if($notifications):?><div class="table-scroll"><table><thead><tr><th>Date</th><th>Type</th><th>Message</th><th>Status</th></tr></thead><tbody><?php foreach($notifications as $notification):?><tr><td><?=e($notification['created_at'])?></td><td><?=e(ucwords(str_replace('_',' ',$notification['type'])))?></td><td><?=e($notification['message'])?></td><td><?=!empty($notification['is_read'])?'Read':'Unread'?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No notifications recorded.</p><?php endif;?></section><section class="panel"><h2>Nominees</h2><?php if($nominees):?><div class="table-scroll"><table><thead><tr><th>Account</th><th>Name</th><th>Relationship</th><th>Date of birth</th><th>Share</th></tr></thead><tbody><?php foreach($nominees as $nominee):?><tr><td><?=e($nominee['account_number'])?></td><td><?=e($nominee['full_name'])?></td><td><?=e($nominee['relationship'])?></td><td><?=e($nominee['date_of_birth']??'—')?></td><td><?=e(number_format((float)$nominee['share_percentage'],2))?>%</td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No nominees recorded for these accounts.</p><?php endif;?></section><?php page_end();
